const ENZYME_TYPES = {
  amylase: { label: "🙂 Salivary amylase", opt: 7, temp: 38, sub: "starch", prod: "maltose", col: "#5B8FE0" },
  pepsin: { label: "🫙 Pepsin", opt: 2, temp: 37, sub: "protein", prod: "peptides", col: "#B56AA0" },
  trypsin: { label: "🧪 Trypsin", opt: 8, temp: 39, sub: "protein", prod: "peptides", col: "#2FA36B" }
};
function enzymeTempFactor(temp, den) {
  if (den) return 0;
  if (temp <= 0) return .03;
  if (temp <= 39) return clamp(.08 + Math.pow(temp / 39, 1.55) * .92, 0, 1.05);
  if (temp >= 62) return 0;
  return clamp(1 - Math.pow((temp - 39) / 23, 1.7), 0, 1);
}
function enzymePhFactor(kind, ph) { const o = ENZYME_TYPES[kind].opt, w = o <= 3 ? 1.55 : 1.9; return Math.exp(-Math.pow((ph - o) / w, 2)); }
function enzymeModel(st, x) {
  const temp = x && x.temp != null ? x.temp : st.temp, pH = x && x.pH != null ? x.pH : st.pH, sub = x && x.sub != null ? x.sub : st.substrate, enz = x && x.enz != null ? x.enz : st.enzyme, inh = x && x.inh != null ? x.inh : st.inhibitor;
  const den = (x && x.den != null ? x.den : st.denatured) || temp >= 62;
  let vmax = enz * enzymeTempFactor(temp, den) * enzymePhFactor(st.kind, pH);
  let km = 24;
  if (inh === "comp") km *= 3.2;
  if (inh === "non") vmax *= .45;
  const sat = sub / (sub + km);
  const rate = clamp(vmax * sat, 0, 100);
  const complexes = Math.round(clamp(rate / 12, 0, 8));
  return { rate:+rate.toFixed(1), vmax:+vmax.toFixed(1), sat:+(sat*100).toFixed(0), tempFactor:enzymeTempFactor(temp, den), phFactor:enzymePhFactor(st.kind, pH), denatured:den, complexes };
}
/* enzyme cause→effect: complementary collisions form E–S complexes; temperature, pH, substrate and inhibitors change the rate. Model is simplified Michaelis–Menten with irreversible heat denaturation. */
function enzymeSim(root) {
  const st = { kind:"amylase", temp:25, pH:6, substrate:35, enzyme:55, inhibitor:"none", graph:"substrate", view:"molecule", denatured:false, t:0, ghosts:[], measures:0, resets:0 };
  const snap = () => { const m = enzymeModel(st); return Object.assign({}, m, { kind:st.kind, optPH:ENZYME_TYPES[st.kind].opt, temp:st.temp, pH:+st.pH.toFixed(1), substrate:st.substrate, enzyme:st.enzyme, inhibitor:st.inhibitor, graph:st.graph, view:st.view, ghosts:st.ghosts.length, measures:st.measures, resets:st.resets, highSub:st.substrate>=80, optimum:m.rate>=55 && st.temp>=35 && st.temp<=41 && Math.abs(st.pH-ENZYME_TYPES[st.kind].opt)<=.7 && !st.denatured }); };
  root.innerHTML = `<div class="simgrid wide"><section class="card"><div class="enzyme-labtabs">${segBtns("enzymeview", [["molecule","🔬 Molecules"],["bench","🧪 Catalase bench"]], st.view)}</div><div id="enzymeScene" class="simsvg nozoom enzyme-svg"></div><div id="enzymeRead" class="enzyme-read"></div><div id="enzymeFlow" class="enzyme-flow"></div></section><section class="card"><h3 style="margin:0">🎛️ Variables</h3><div class="simctl"><div><b>Enzyme</b>${segBtns("enzymekind", Object.entries(ENZYME_TYPES).map(([k,v])=>[k,v.label]), st.kind)}</div><label class="enzyme-range small"><b>🌡️ Temperature <span id="enzymeTempLab">25 °C</span></b><input id="enzymeTemp" type="range" min="0" max="70" value="25"></label><label class="enzyme-range small"><b>pH <span id="enzymePhLab">6.0</span></b><input id="enzymePH" type="range" min="1" max="10" step="0.1" value="6"></label><label class="enzyme-range small"><b>⬡ Substrate <span id="enzymeSubLab">35%</span></b><input id="enzymeSub" type="range" min="0" max="100" value="35"></label><label class="enzyme-range small"><b>🔑 Enzyme <span id="enzymeEnzLab">55%</span></b><input id="enzymeEnz" type="range" min="0" max="100" value="55"></label><div><b>Inhibitor</b>${segBtns("enzymeinh", [["none","✅ None"],["comp","🚫 Competitive"],["non","🧲 Non-competitive"]], st.inhibitor)}</div><div><b>Graph</b>${segBtns("enzymegraph", [["temp","Temp"],["pH","pH"],["substrate","Substrate"],["enzyme","Enzyme"]], st.graph)}</div></div><div class="row simbtns"><button class="btn" id="enzymeRecord">📈 Save curve</button><button class="btn plain" id="enzymeFresh">🧼 Fresh enzyme</button></div><div id="enzymeGraph" class="simsvg nozoom enzyme-svg"></div><div class="enzyme-note" id="enzymeWhy"></div></section></div>`;
  const setSeg = (name, key, cb) => root.querySelectorAll(`[data-${name}]`).forEach(b => b.onclick = () => { SFX.tap(); st[key] = b.dataset[name]; root.querySelectorAll(`[data-${name}]`).forEach(x => x.setAttribute("aria-checked", x === b)); if (key === "kind") { st.pH = ENZYME_TYPES[st.kind].opt; root.querySelector("#enzymePH").value = st.pH; st.denatured = false; } cb && cb(); });
  setSeg("enzymeview", "view"); setSeg("enzymekind", "kind"); setSeg("enzymeinh", "inhibitor"); setSeg("enzymegraph", "graph");
  root.querySelector("#enzymeTemp").oninput = e => { st.temp = Number(e.target.value); if (st.temp >= 62) st.denatured = true; };
  root.querySelector("#enzymePH").oninput = e => st.pH = Number(e.target.value);
  root.querySelector("#enzymeSub").oninput = e => st.substrate = Number(e.target.value);
  root.querySelector("#enzymeEnz").oninput = e => st.enzyme = Number(e.target.value);
  root.querySelector("#enzymeFresh").onclick = () => { SFX.item(); st.denatured = false; st.temp = Math.min(st.temp, 40); root.querySelector("#enzymeTemp").value = st.temp; st.resets++; };
  root.querySelector("#enzymeRecord").onclick = () => { SFX.item(); st.ghosts.push({ graph:st.graph, kind:st.kind, temp:st.temp, pH:st.pH, substrate:st.substrate, enzyme:st.enzyme, inhibitor:st.inhibitor, denatured:st.denatured, col:ENZYME_TYPES[st.kind].col }); st.ghosts = st.ghosts.slice(-5); st.measures++; };
  simProbe(() => snap());
  simLoop(root, dt => {
    st.t += dt;
    if (st.temp >= 62) st.denatured = true;
    const m = snap();
    root.querySelector("#enzymeTempLab").textContent = `${st.temp} °C`; root.querySelector("#enzymePhLab").textContent = st.pH.toFixed(1); root.querySelector("#enzymeSubLab").textContent = `${st.substrate}%`; root.querySelector("#enzymeEnzLab").textContent = `${st.enzyme}%`;
    root.querySelector("#enzymeScene").innerHTML = st.view === "bench" ? enzymeBenchSvg(st,m) : enzymeMolSvg(st,m);
    root.querySelector("#enzymeRead").innerHTML = enzymeReadHtml(st,m);
    root.querySelector("#enzymeFlow").innerHTML = enzymeFlowHtml(st,m);
    root.querySelector("#enzymeGraph").innerHTML = enzymeGraphSvg(st);
    root.querySelector("#enzymeWhy").innerHTML = enzymeWhyHtml(st,m);
  });
}
function enzymeReadHtml(st,m){ const tile=(ic,lab,val,bar,c,cls="")=>`<div class="enzyme-tile ${cls}"><b>${ic} ${lab}</b><span class="enzyme-big">${val}</span><div class="enzyme-bar"><i style="--w:${clamp(bar,0,100)}%;--c:${c}"></i></div></div>`; return tile("⚡","Rate",`${m.rate}/100`,m.rate,m.denatured?"#B9A99A":"#3FA06B",m.denatured?"enzyme-hot":"")+tile("🤝","E–S complex",`${m.complexes} shown`,m.complexes/8*100,"#5B8FE0")+tile("📈","Vmax",`${m.vmax}/100`,m.vmax,"#8E5BD6")+tile("🧱","Active sites",`${m.sat}% full`,m.sat,"#F2A23A"); }
function enzymeWhyHtml(st,m){ if(m.denatured) return "🔥 Denatured: heat changed the active site. Cooling cannot restore this enzyme."; if(st.inhibitor==="comp") return "🚫 Competitive inhibitor blocks active sites. Adding more substrate can partly overcome it."; if(st.inhibitor==="non") return "🧲 Non-competitive inhibitor changes active-site shape. More substrate cannot restore Vmax."; if(st.substrate>75&&m.sat>70) return "🧱 Plateau: most active sites are occupied, so enzyme concentration limits the rate."; if(st.temp<20) return "❄️ Low temperature: fewer kinetic-energy collisions. Not denatured."; return "✅ Complementary collisions form complexes → products leave → enzyme is reused."; }
function enzymeFlowHtml(st,m){ const steps=[["collision","⬡ Collide",m.rate>8],["fit","🔑 Fit",m.rate>18&&!m.denatured&&st.inhibitor!=="non"],["complex","🤝 E–S",m.complexes>0],["product","✨ Products",m.rate>25],["reuse","🔁 Enzyme reused",!m.denatured&&m.rate>10]]; return steps.map((s,i)=>`<span class="enzyme-step ${s[2]?"on":""}">${s[1]}</span>${i<steps.length-1?`<span class="enzyme-arrow">→</span>`:""}`).join(""); }
function enzymeMolSvg(st,m){ const type=ENZYME_TYPES[st.kind], den=m.denatured, wig=Math.sin(st.t*2)*4; const subs=Array.from({length:8},(_,i)=>{ const p=(st.t*(.14+m.rate/700)+i/8)%1, x=520-410*p, y=78+(i%4)*62+Math.sin(st.t*2+i)*14; const good=i%3!==1; return `<g transform="translate(${x.toFixed(1)} ${y.toFixed(1)}) rotate(${(p*180+i*23).toFixed(1)})"><path d="M0,-14 L18,0 L0,14 L-18,0Z" fill="${good?"#FFD66B":"#D7C7F2"}" stroke="${CO}" stroke-width="3"/></g>`; }).join(""); return `<svg viewBox="0 0 680 390" role="img" aria-label="Molecular enzyme with active site, substrate collisions and products"><defs><marker id="enzymeArr" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#3FA06B"/></marker></defs><rect width="680" height="390" rx="18" fill="#F6FAFF"/><g transform="translate(70 62)"><path d="M54 34 C115 -18 252 8 274 100 C296 190 210 276 110 250 C22 226 -24 114 54 34Z" fill="${den?"#D8D1C9":"#B8E0CE"}" stroke="${CO}" stroke-width="5"/><path d="M198 80 C165 88 146 110 148 143 C151 176 178 184 206 174" fill="none" stroke="${den||st.inhibitor==="non"?"#D65A45":"#246B50"}" stroke-width="18" stroke-linecap="round"/><text x="132" y="34" font-size="22" font-weight="950" fill="${CO}">enzyme</text><text x="222" y="136" font-size="21" font-weight="950" fill="${CO}">active site</text>${st.inhibitor==="comp"?`<g transform="translate(194 132)"><circle r="25" fill="#E9573F" stroke="${CO}" stroke-width="4"/><text y="7" text-anchor="middle" font-size="22" font-weight="950" fill="#fff">I</text></g>`:""}${st.inhibitor==="non"?`<g transform="translate(76 198)"><circle r="22" fill="#8E5BD6" stroke="${CO}" stroke-width="4"/><text y="7" text-anchor="middle" font-size="20" font-weight="950" fill="#fff">I</text></g>`:""}${m.complexes>0&&!den&&st.inhibitor!=="comp"?`<g transform="translate(205 ${136+wig})"><path d="M0,-18 L24,0 L0,18 L-24,0Z" fill="#FFD66B" stroke="${CO}" stroke-width="4"/></g>`:""}</g>${subs}<g transform="translate(498 260)"><circle cx="0" cy="0" r="13" fill="#88D8FF" stroke="${CO}" stroke-width="3"/><circle cx="34" cy="10" r="13" fill="#88D8FF" stroke="${CO}" stroke-width="3"/><text x="18" y="52" text-anchor="middle" font-size="20" font-weight="950" fill="${CO}">products</text></g><path d="M384 254 C430 272 450 276 486 268" stroke="#3FA06B" stroke-width="5" fill="none" marker-end="url(#enzymeArr)"/><text x="340" y="32" text-anchor="middle" font-size="24" font-weight="950" fill="${CO}">${den?"Denaturation: active site changed":"Lock-and-key collisions"}</text><text x="342" y="366" text-anchor="middle" font-size="20" font-weight="900" fill="${CO}">${type.label}: optimum pH ${type.opt}, about ${type.temp} °C</text></svg>`; }
function enzymeBenchSvg(st,m){ const foam=clamp(m.rate*2.25,2,178), bubbles=Math.round(m.rate/4); return `<svg viewBox="0 0 680 360" role="img" aria-label="Catalase in potato or liver with hydrogen peroxide making oxygen foam"><rect width="680" height="360" rx="18" fill="#FFF8EC"/><path d="M0 292 H680 V360 H0Z" fill="#E7D0B7"/><g transform="translate(92 42)"><path d="M54 10 H202 L180 278 H76Z" fill="#F7FBFF" stroke="${CO}" stroke-width="5"/><path d="M80 ${278-foam} H176 L180 278 H76Z" fill="#F7E8B8" stroke="#D8B35B" stroke-width="2"/><path d="M84 220 H172 L182 278 H74Z" fill="#F2C879" opacity=".7"/><text x="128" y="305" text-anchor="middle" font-size="21" font-weight="950" fill="${CO}">H₂O₂ + catalase</text>${Array.from({length:Math.min(22,bubbles)},(_,i)=>`<circle cx="${92+(i*37)%82}" cy="${240-((i*31+st.t*45)%(foam+24))}" r="${4+i%5}" fill="#fff" stroke="#9CC7E8" stroke-width="2"/>`).join("")}</g><g transform="translate(354 74)"><rect x="0" y="122" width="214" height="44" rx="18" fill="#C79B67" stroke="${CO}" stroke-width="4"/><circle cx="44" cy="104" r="28" fill="#D7A15E" stroke="${CO}" stroke-width="4"/><circle cx="106" cy="94" r="34" fill="#B95F5F" stroke="${CO}" stroke-width="4"/><text x="108" y="16" text-anchor="middle" font-size="23" font-weight="950" fill="${CO}">O₂ foam height</text><text x="108" y="58" text-anchor="middle" font-size="30" font-weight="950" fill="#2C7A4B">${Math.round(foam)} mm</text><text x="108" y="215" text-anchor="middle" font-size="20" font-weight="900" fill="${CO}">bubbles ${Math.round(m.rate)} min⁻¹</text></g><text x="340" y="334" text-anchor="middle" font-size="19" font-weight="900" fill="${CO}">Fair test: same H₂O₂ volume, tissue mass and time; change one variable.</text></svg>`; }
function enzymeGraphSvg(st){ const W=360,H=210,L=40,B=170,R=344,T=22; const xs={temp:[0,70,"Temperature / °C"],pH:[1,10,"pH"],substrate:[0,100,"Substrate / %"],enzyme:[0,100,"Enzyme / %"]}[st.graph]; const X=x=>L+(x-xs[0])/(xs[1]-xs[0])*(R-L), Y=y=>B-y/100*(B-T); const curve=s=>Array.from({length:46},(_,i)=>{ const x=xs[0]+(xs[1]-xs[0])*i/45, m=enzymeModel(Object.assign({},st,s), { temp:s.graph==="temp"?x:s.temp, pH:s.graph==="pH"?x:s.pH, sub:s.graph==="substrate"?x:s.substrate, enz:s.graph==="enzyme"?x:s.enzyme, inh:s.inhibitor, den:s.denatured }); return `${X(x).toFixed(1)},${Y(m.rate).toFixed(1)}`; }).join(" "); const now={graph:st.graph, temp:st.temp, pH:st.pH, substrate:st.substrate, enzyme:st.enzyme, inhibitor:st.inhibitor, denatured:st.denatured, col:"#2F9E5B"}; const curX={temp:st.temp,pH:st.pH,substrate:st.substrate,enzyme:st.enzyme}[st.graph], curY=enzymeModel(st).rate; return `<svg viewBox="0 0 360 210" role="img" aria-label="Enzyme rate graph"><rect width="360" height="210" rx="12" fill="#fff"/><path d="M${L} ${T} V${B} H${R}" stroke="${CO}" stroke-width="2" fill="none"/>${[0,25,50,75,100].map(y=>`<line x1="${L}" x2="${R}" y1="${Y(y)}" y2="${Y(y)}" stroke="#EEE4D8"/><text x="34" y="${Y(y)+4}" text-anchor="end" font-size="11" fill="#7A6A66">${y}</text>`).join("")}${st.ghosts.filter(g=>g.graph===st.graph).map(g=>`<polyline class="enzyme-ghost" points="${curve(g)}" fill="none" stroke="${g.col}" stroke-width="3"/>`).join("")}<polyline points="${curve(now)}" fill="none" stroke="#2F9E5B" stroke-width="4" stroke-linecap="round"/><circle cx="${X(curX)}" cy="${Y(curY)}" r="6" fill="#E9573F" stroke="#fff" stroke-width="2"/><text x="194" y="15" text-anchor="middle" font-size="13" font-weight="950" fill="${CO}">rate / a.u.</text><text x="190" y="202" text-anchor="middle" font-size="13" font-weight="950" fill="${CO}">${xs[2]}</text><text x="322" y="35" text-anchor="end" font-size="11" font-weight="900" fill="#7A6A66">ghosts ${st.ghosts.filter(g=>g.graph===st.graph).length}</text></svg>`; }

const PHOTO_COLOUR = { white:["💡 White",1,"#FFF5CC"], red:["🔴 Red",.92,"#FFB1A8"], blue:["🔵 Blue",.86,"#B8D6FF"], green:["🟢 Green",.28,"#BDE8BF"], dark:["🌑 Dark",0,"#2C3140"] };
function photoLight(distance){ return clamp(100*Math.pow(20/distance,2),0,100); }
function photoTempFactor(t){ if(t<5) return .1; if(t<=30) return clamp(.22+t/30*.78,0,1); if(t>=48) return .08; return clamp(1-Math.pow((t-30)/18,1.65),.08,1); }
function photoModel(st,x){ const intensity=x&&x.intensity!=null?x.intensity:photoLight(st.distance), co2=x&&x.co2!=null?x.co2:st.co2, temp=x&&x.temp!=null?x.temp:st.temp, col=x&&x.col?x.col:st.colour; const cf=PHOTO_COLOUR[col][1], tf=photoTempFactor(temp), co2f=clamp(co2/80,0,1.25); const lightUse=intensity/(intensity+22); const vmax=68*clamp(co2f,0,1.15)*tf*cf; const rate=clamp(vmax*lightUse,0,80); let limit="Light"; if(cf<.35) limit="Light colour"; else if(intensity>55&&co2<45) limit="CO₂"; else if(intensity>55&&(temp<18||temp>36)) limit="Temperature"; else if(intensity>60) limit="CO₂ / temperature"; const gp = col==="dark" ? 88 : co2<8 ? 18 : clamp(30+rate/1.6,15,85); const rubp = col==="dark" ? 20 : co2<8 ? 86 : clamp(70-rate/2,18,82); return { intensity:+intensity.toFixed(1), rate:+rate.toFixed(1), bubbles:+(rate*.9).toFixed(0), limit, tempFactor:tf, gp:+gp.toFixed(0), rubp:+rubp.toFixed(0), vmax:+vmax.toFixed(1) }; }
/* photo cause→effect: light, CO₂ and temperature feed different stages; the scarcest factor limits O₂ bubble rate. Model simplifies many enzymes into one temperature factor. */
function photoSim(root){
  const st={distance:55, co2:35, temp:22, colour:"white", graph:"light", view:"bench", t:0, ghosts:[], records:0};
  const snap=()=>{ const m=photoModel(st); return Object.assign({},m,{distance:st.distance,co2:st.co2,temp:st.temp,colour:st.colour,graph:st.graph,view:st.view,ghosts:st.ghosts.length,records:st.records,closeLamp:st.distance<=20,highCO2:st.co2>=70,green:st.colour==="green"}); };
  root.innerHTML=`<div class="simgrid wide"><section class="card"><div><b class="small">View</b>${segBtns("photoview", [["bench","🧪 Pondweed"],["chloroplast","🟢 Chloroplast"]], st.view)}</div><div id="photoScene" class="simsvg nozoom photo-svg"></div><div id="photoRead" class="photo-read"></div><div id="photoFlow" class="photo-flow"></div></section><section class="card"><h3 style="margin:0">🎛️ Conditions</h3><div class="simctl"><label class="photo-range small"><b>💡 Lamp distance <span id="photoDistLab">55 cm</span></b><input id="photoDist" type="range" min="8" max="80" value="55"></label><label class="photo-range small"><b>CO₂ (NaHCO₃) <span id="photoCO2Lab">35%</span></b><input id="photoCO2" type="range" min="0" max="100" value="35"></label><label class="photo-range small"><b>🌡️ Temperature <span id="photoTempLab">22 °C</span></b><input id="photoTemp" type="range" min="5" max="45" value="22"></label><div><b>Light colour</b>${segBtns("photocolour", Object.entries(PHOTO_COLOUR).map(([k,v])=>[k,v[0]]), st.colour)}</div></div><div class="row simbtns"><button class="btn" id="photoRecord">📈 Save curve</button><button class="btn plain" id="photoGreenhouse">🏙️ HK greenhouse</button></div><div id="photoGraph" class="simsvg nozoom photo-svg"></div><div class="photo-note photo-limit" id="photoWhy"></div></section></div>`;
  const setSeg=(name,key)=>root.querySelectorAll(`[data-${name}]`).forEach(b=>b.onclick=()=>{SFX.tap(); st[key]=b.dataset[name]; root.querySelectorAll(`[data-${name}]`).forEach(x=>x.setAttribute("aria-checked",x===b));});
  setSeg("photoview","view"); setSeg("photocolour","colour");
  root.querySelector("#photoDist").oninput=e=>st.distance=Number(e.target.value); root.querySelector("#photoCO2").oninput=e=>st.co2=Number(e.target.value); root.querySelector("#photoTemp").oninput=e=>st.temp=Number(e.target.value);
  root.querySelector("#photoRecord").onclick=()=>{SFX.item(); st.ghosts.push({distance:st.distance,co2:st.co2,temp:st.temp,colour:st.colour,col:PHOTO_COLOUR[st.colour][2]}); st.ghosts=st.ghosts.slice(-5); st.records++;};
  root.querySelector("#photoGreenhouse").onclick=()=>{SFX.item(); st.co2=80; st.temp=28; st.distance=18; st.colour="white"; root.querySelector("#photoCO2").value=st.co2; root.querySelector("#photoTemp").value=st.temp; root.querySelector("#photoDist").value=st.distance; root.querySelectorAll(`[data-photocolour]`).forEach(x=>x.setAttribute("aria-checked",x.dataset.photocolour===st.colour));};
  simProbe(()=>snap());
  simLoop(root,dt=>{ st.t+=dt; const m=snap(); root.querySelector("#photoDistLab").textContent=`${st.distance} cm`; root.querySelector("#photoCO2Lab").textContent=`${st.co2}%`; root.querySelector("#photoTempLab").textContent=`${st.temp} °C`; root.querySelector("#photoScene").innerHTML=st.view==="chloroplast"?photoChloroplastSvg(st,m):photoBenchSvg(st,m); root.querySelector("#photoRead").innerHTML=photoReadHtml(st,m); root.querySelector("#photoFlow").innerHTML=photoFlowHtml(st,m); root.querySelector("#photoGraph").innerHTML=photoGraphSvg(st); root.querySelector("#photoWhy").innerHTML=`🧱 <b>Limiting factor now: ${m.limit}</b>. ${m.limit==="Light"?"Move the lamp closer or choose red/blue light.":m.limit==="CO₂"?"Add sodium hydrogencarbonate to raise the plateau.":m.limit==="Temperature"?"Warm towards about 25–30 °C; too hot slows enzymes.":m.limit==="Light colour"?"Green is mostly reflected, so it is least useful.":"At high light, CO₂ and temperature set the plateau."}`; });
}
function photoReadHtml(st,m){ const tile=(ic,lab,val,bar,c)=>`<div class="photo-tile"><b>${ic} ${lab}</b><span class="photo-big">${val}</span><div class="photo-bar"><i style="--w:${clamp(bar,0,100)}%;--c:${c}"></i></div></div>`; return tile("🫧","O₂ bubbles",`${m.bubbles} min⁻¹`,m.bubbles/72*100,"#3FA06B")+tile("💡","Light intensity",`${m.intensity}%`,m.intensity,"#F2A23A")+tile("CO₂","NaHCO₃",`${st.co2}%`,st.co2,"#5B8FE0")+tile("🧱","Limit",m.limit,70,"#8E5BD6"); }
function photoFlowHtml(st,m){ const on=m.rate>2, co2=st.co2>5; const steps=[["☀️ Light",on],["💦 Photolysis",on],["O₂ + ATP + NADPH",on],["CO₂ fixed",co2&&on],["🍬 Sugar/starch",m.rate>18&&co2]]; return steps.map((s,i)=>`<span class="photo-step ${s[1]?"on":""}">${s[0]}</span>${i<steps.length-1?`<span class="photo-arrow">→</span>`:""}`).join(""); }
function photoBenchSvg(st,m){ const lampX=94+st.distance/80*192, beam=clamp(160-st.distance,40,142); return `<svg viewBox="0 0 680 390" role="img" aria-label="Hydrilla pondweed in sodium hydrogencarbonate solution under a lamp producing oxygen bubbles"><rect width="680" height="390" rx="18" fill="#F4FAFF"/><path d="M0 304 H680 V390 H0Z" fill="#D7C3A2"/><g transform="translate(${lampX} 36)"><path d="M0 32 h88 l-18 48 h-52Z" fill="${PHOTO_COLOUR[st.colour][2]}" stroke="${CO}" stroke-width="5"/><path d="M44 80 V256" stroke="${CO}" stroke-width="8"/><text x="44" y="28" text-anchor="middle" font-size="22" font-weight="950" fill="${CO}">lamp</text></g><path d="M${lampX+44} 118 C${lampX+30} 180 ${338-beam} 210 290 285" stroke="${PHOTO_COLOUR[st.colour][2]}" stroke-width="${Math.max(10,m.intensity/5)}" opacity=".42" fill="none"/><g transform="translate(296 56)"><path d="M34 0 H252 L232 300 H54Z" fill="#DFF4FF" stroke="${CO}" stroke-width="5"/><path d="M58 84 H228 L216 284 H70Z" fill="#AFDDF2" opacity=".72"/><text x="142" y="31" text-anchor="middle" font-size="22" font-weight="950" fill="${CO}">test tube</text><text x="142" y="67" text-anchor="middle" font-size="20" font-weight="900" fill="${CO}">NaHCO₃ solution</text><g transform="translate(112 216)">${[-38,-24,-10,4,18,32].map((x,i)=>`<path d="M0 46 C${x} ${24-i*4} ${x} ${6-i*7} ${x/3} ${-8-i*2}" stroke="#2F9E5B" stroke-width="7" fill="none" stroke-linecap="round"/><ellipse cx="${x/3}" cy="${-12-i*2}" rx="18" ry="8" fill="#55B867" stroke="${CO}" stroke-width="2" transform="rotate(${x})"/>`).join("")}</g>${Array.from({length:Math.min(24,Math.round(m.bubbles/3))},(_,i)=>`<circle class="photo-bubble" cx="${96+(i*37)%88}" cy="${210-((i*29+st.t*45)%(150))}" r="${3+i%4}" fill="#fff" stroke="#4CA9D8" stroke-width="2"/>`).join("")}</g><g transform="translate(40 278)"><rect width="232" height="56" rx="18" fill="#fff" stroke="${CO}" stroke-width="4"/><text x="116" y="24" text-anchor="middle" font-size="19" font-weight="950" fill="${CO}">Count oxygen bubbles</text><text x="116" y="48" text-anchor="middle" font-size="24" font-weight="950" fill="#2F9E5B">${m.bubbles} bubbles min⁻¹</text></g><text x="340" y="367" text-anchor="middle" font-size="19" font-weight="900" fill="${CO}">Light intensity follows 1/d², so distance matters.</text></svg>`; }
function photoChloroplastSvg(st,m){ const gpW=m.gp, ruW=m.rubp; return `<svg viewBox="0 0 680 430" role="img" aria-label="Detailed chloroplast with grana, thylakoids, stroma, starch grain and photosynthesis stages"><rect width="680" height="430" rx="18" fill="#F5FFF2"/><g transform="translate(54 52)"><ellipse cx="286" cy="152" rx="254" ry="132" fill="#CBEFC7" stroke="${CO}" stroke-width="5"/><ellipse cx="286" cy="152" rx="232" ry="112" fill="#E6FFE2" stroke="#3FA06B" stroke-width="4"/><text x="286" y="32" text-anchor="middle" font-size="24" font-weight="950" fill="${CO}">chloroplast envelope: double membrane</text><text x="94" y="252" font-size="22" font-weight="950" fill="${CO}">stroma</text><ellipse cx="418" cy="206" rx="44" ry="26" fill="#F4D063" stroke="${CO}" stroke-width="4"/><text x="418" y="212" text-anchor="middle" font-size="19" font-weight="950" fill="${CO}">starch</text>${[0,1,2].map((g)=>`<g transform="translate(${122+g*142} 96)">${[0,1,2,3,4].map(i=>`<ellipse cx="0" cy="${i*18}" rx="48" ry="11" fill="#2F9E5B" stroke="${CO}" stroke-width="2"/>`).join("")}<text x="0" y="114" text-anchor="middle" font-size="20" font-weight="950" fill="${CO}">granum</text></g>`).join("")}<path d="M170 144 C226 124 262 170 322 146 C364 130 400 146 440 128" fill="none" stroke="#2F9E5B" stroke-width="10" opacity=".5"/><text x="488" y="120" font-size="21" font-weight="950" fill="${CO}">thylakoid</text></g><g transform="translate(38 342)"><rect width="282" height="54" rx="16" fill="#E6F8EC" stroke="#3FA06B" stroke-width="4"/><text x="141" y="23" text-anchor="middle" font-size="19" font-weight="950" fill="${CO}">Light-dependent</text><text x="141" y="47" text-anchor="middle" font-size="18" font-weight="900" fill="${CO}">H₂O → O₂ + ATP + NADPH</text></g><g transform="translate(358 342)"><rect width="282" height="54" rx="16" fill="#FFF4D6" stroke="#D39A19" stroke-width="4"/><text x="141" y="23" text-anchor="middle" font-size="19" font-weight="950" fill="${CO}">Calvin cycle</text><text x="141" y="47" text-anchor="middle" font-size="18" font-weight="900" fill="${CO}">CO₂ + RuBP → GP → triose</text></g><g transform="translate(468 58)"><text x="80" y="0" text-anchor="middle" font-size="20" font-weight="950" fill="${CO}">Molecule levels</text><text x="0" y="36" font-size="18" font-weight="900" fill="${CO}">GP</text><rect x="60" y="18" width="120" height="20" rx="10" fill="#EEE4D8"/><rect x="60" y="18" width="${gpW*1.2}" height="20" rx="10" fill="#5B8FE0"/><text x="0" y="72" font-size="18" font-weight="900" fill="${CO}">RuBP</text><rect x="60" y="54" width="120" height="20" rx="10" fill="#EEE4D8"/><rect x="60" y="54" width="${ruW*1.2}" height="20" rx="10" fill="#8E5BD6"/></g></svg>`; }
function photoGraphSvg(st){ const W=360,H=210,L=42,B=170,R=344,T=22; const X=x=>L+x/100*(R-L), Y=y=>B-y/80*(B-T); const curve=s=>Array.from({length:50},(_,i)=>{ const inten=i/49*100, y=photoModel(Object.assign({},st,s),{intensity:inten,co2:s.co2,temp:s.temp,col:s.colour}).rate; return `${X(inten).toFixed(1)},${Y(y).toFixed(1)}`; }).join(" "); const m=photoModel(st), cur=photoLight(st.distance); return `<svg viewBox="0 0 360 210" role="img" aria-label="Photosynthesis rate against light intensity graph"><rect width="360" height="210" rx="12" fill="#fff"/><path d="M${L} ${T} V${B} H${R}" stroke="${CO}" stroke-width="2" fill="none"/>${[0,20,40,60,80].map(y=>`<line x1="${L}" x2="${R}" y1="${Y(y)}" y2="${Y(y)}" stroke="#EEE4D8"/><text x="36" y="${Y(y)+4}" text-anchor="end" font-size="11" fill="#7A6A66">${y}</text>`).join("")}${st.ghosts.map(g=>`<polyline class="photo-ghost" points="${curve(g)}" fill="none" stroke="${g.col}" stroke-width="3"/>`).join("")}<polyline points="${curve(st)}" fill="none" stroke="#2F9E5B" stroke-width="4" stroke-linecap="round"/><circle cx="${X(cur)}" cy="${Y(m.rate)}" r="6" fill="#E9573F" stroke="#fff" stroke-width="2"/><text x="194" y="15" text-anchor="middle" font-size="13" font-weight="950" fill="${CO}">O₂ bubbles min⁻¹</text><text x="190" y="202" text-anchor="middle" font-size="13" font-weight="950" fill="${CO}">light intensity / %</text><text x="324" y="35" text-anchor="end" font-size="11" font-weight="900" fill="#7A6A66">plateau shifts up with CO₂ / warmth</text></svg>`; }

function respTempFactor(t){ if(t<5) return .15; if(t<=35) return .25+t/35*.85; if(t>=55) return .05; return clamp(1.1-Math.pow((t-35)/20,1.5),.05,1.1); }
function respModel(st){ const live=st.organism==="germ"||st.organism==="maggot", tf=respTempFactor(st.temp), base=st.organism==="maggot"?1.15:st.organism==="germ"?1:0.04; const o2rate=+(live?base*tf*7.5:0.15).toFixed(2); const movement=+(st.koh?o2rate*1.6:o2rate*.18).toFixed(1); const anaer=st.oxygen==="off", yeast=st.cell==="yeast"; const atp=anaer?2:38, products=anaer?(yeast?"ethanol + CO₂":"lactic acid") : "CO₂ + H₂O", site=anaer?"cytoplasm only":"cytoplasm + mitochondrion"; const yco2=+(yeast&&anaer?tf*42:yeast?tf*14:0).toFixed(0); return { live, tempFactor:tf, o2rate, movement, atp, products, site, yco2, debt:anaer&&st.cell==="muscle"?Math.round(30+tf*50):0 }; }
/* resp cause→effect: oxygen availability decides whether pyruvate enters mitochondria for high ATP or stays in cytoplasm for fermentation. Respirometer volume change is simplified to O₂ uptake after CO₂ absorption. */
function respSim(root){
  const st={view:"cell", temp:25, organism:"germ", koh:true, oxygen:"on", cell:"muscle", run:false, fast:false, t:0, distance:0, co2:0, runs:0};
  const snap=()=>{ const m=respModel(st); return Object.assign({},m,{view:st.view,temp:st.temp,organism:st.organism,koh:st.koh,oxygen:st.oxygen,cell:st.cell,running:st.run,distance:+st.distance.toFixed(1),co2:+st.co2.toFixed(0),control:st.organism==="boiled"||st.organism==="beads", respirometerReady:st.view==="respiro"&&st.koh&&m.live, yeastReady:st.view==="yeast"&&st.cell==="yeast"&&st.oxygen==="off", aerobic:st.oxygen==="on"}); };
  root.innerHTML=`<div class="simgrid wide"><section class="card"><div><b class="small">Mode</b>${segBtns("respview", [["cell","🧬 Cell view"],["respiro","📏 Respirometer"],["yeast","🍞 Yeast tube"]], st.view)}</div><div id="respScene" class="simsvg nozoom resp-svg"></div><div class="row simbtns"><button class="btn" id="respRun">▶ Run</button><button class="btn plain" id="respFast">⏩ Fast</button><button class="btn plain" id="respReset">↺ Reset</button></div><div id="respRead" class="resp-read"></div></section><section class="card"><h3 style="margin:0">🎛️ Set-up</h3><div class="simctl"><label class="resp-range small"><b>🌡️ Water bath <span id="respTempLab">25 °C</span></b><input id="respTemp" type="range" min="5" max="50" value="25"></label><div><b>Respirometer</b>${segBtns("resporg", [["germ","🌱 Germinating seeds"],["maggot","🐛 Maggots / woodlice"],["boiled","🥔 Boiled seeds"],["beads","⚪ Glass beads"]], st.organism)}</div><label class="chk small"><input id="respKoh" type="checkbox" checked> ⚪ Soda lime / KOH absorbs CO₂</label><div><b>Oxygen</b>${segBtns("respoxygen", [["on","O₂ On"],["off","O₂ Off / oil layer"]], st.oxygen)}</div><div><b>Cell type</b>${segBtns("respcell", [["muscle","💪 Muscle"],["yeast","🍞 Yeast"]], st.cell)}</div></div><div id="respFlow" class="resp-flow"></div><div class="resp-note" id="respWhy"></div></section></div>`;
  const setSeg=(name,key)=>root.querySelectorAll(`[data-${name}]`).forEach(b=>b.onclick=()=>{SFX.tap(); st[key]=b.dataset[name]; root.querySelectorAll(`[data-${name}]`).forEach(x=>x.setAttribute("aria-checked",x===b));});
  setSeg("respview","view"); setSeg("resporg","organism"); setSeg("respoxygen","oxygen"); setSeg("respcell","cell");
  root.querySelector("#respTemp").oninput=e=>st.temp=Number(e.target.value); root.querySelector("#respKoh").onchange=e=>{st.koh=e.target.checked;SFX.tap();};
  root.querySelector("#respRun").onclick=()=>{SFX.tap();st.run=!st.run;root.querySelector("#respRun").textContent=st.run?"⏸ Pause":"▶ Run";st.runs++;}; root.querySelector("#respFast").onclick=()=>{SFX.tap();st.fast=!st.fast;root.querySelector("#respFast").textContent=st.fast?"⏩ Fast: on":"⏩ Fast";}; root.querySelector("#respReset").onclick=()=>{SFX.tap();st.distance=0;st.co2=0;st.t=0;st.run=false;root.querySelector("#respRun").textContent="▶ Run";};
  simProbe(()=>snap());
  simLoop(root,dt=>{ const m=respModel(st), speed=st.run?dt*(st.fast?5:1):0; st.t+=dt; if(speed){st.distance+=m.movement*speed/8; st.co2+=m.yco2*speed/18;} const p=snap(); root.querySelector("#respTempLab").textContent=`${st.temp} °C`; root.querySelector("#respScene").innerHTML=st.view==="respiro"?respRespiroSvg(st,p):st.view==="yeast"?respYeastSvg(st,p):respCellSvg(st,p); root.querySelector("#respRead").innerHTML=respReadHtml(st,p); root.querySelector("#respFlow").innerHTML=respFlowHtml(st,p); root.querySelector("#respWhy").innerHTML=respWhyHtml(st,p); });
}
function respReadHtml(st,m){ const tile=(ic,lab,val,bar,c)=>`<div class="resp-tile"><b>${ic} ${lab}</b><span class="resp-big">${val}</span><div class="resp-bar"><i style="--w:${clamp(bar,0,100)}%;--c:${c}"></i></div></div>`; return tile("📏","Liquid movement",`${m.movement} mm min⁻¹`,m.movement/14*100,"#5B8FE0")+tile("O₂","O₂ uptake",`${m.o2rate} units`,m.o2rate/9*100,"#3FA06B")+tile("🔋","ATP/glucose",m.atp,m.atp/38*100,"#F2A23A")+tile("🧪","Products",m.products,m.atp/38*100,"#8E5BD6"); }
function respFlowHtml(st,m){ const aerobic=st.oxygen==="on"; const items=aerobic?["🍬 Glucose","✂️ Glycolysis","🔄 Krebs","〰️ ETC + O₂","🔋 ~38 ATP"]:(st.cell==="yeast"?["🍬 Glucose","✂️ Glycolysis","🚫 No O₂","🍞 Ethanol + CO₂","🔋 2 ATP"]:["🍬 Glucose","✂️ Glycolysis","🚫 No O₂","💪 Lactic acid","🔋 2 ATP"]); return items.map((x,i)=>`<span class="resp-step ${i<2||st.run||st.view==="cell"?"on":""}">${x}</span>${i<items.length-1?`<span class="resp-arrow">→</span>`:""}`).join(""); }
function respWhyHtml(st,m){ if(st.view==="respiro") return st.koh?"⚪ Soda lime/KOH absorbs CO₂. Gas volume falls as O₂ is used, so liquid moves towards organisms.":"Without KOH, CO₂ replaces much of the O₂ used, so movement is small."; if(st.view==="yeast") return st.oxygen==="off"?"🍞 Oil keeps oxygen out. Yeast ferments glucose to ethanol + CO₂, turning limewater milky.":"With oxygen, yeast respires aerobically, so fermentation bubbles are lower."; return st.oxygen==="on"?"✅ With oxygen: pyruvate enters mitochondria; Krebs cycle + oxidative phosphorylation make most ATP.":(st.cell==="muscle"?"🏃 No oxygen in muscle: lactic acid forms. Oxygen debt is needed later.":"🍞 No oxygen in yeast: ethanol and CO₂ form; only 2 ATP."); }
function respRespiroSvg(st,m){ const x=500-clamp(st.distance,0,90)*3; return `<svg viewBox="0 0 680 390" role="img" aria-label="Respirometer with organisms, soda lime, capillary tube and coloured liquid"><rect width="680" height="390" rx="18" fill="#F7FBFF"/><path d="M0 300 H680 V390 H0Z" fill="#E2D0BB"/><g transform="translate(70 72)"><rect x="0" y="74" width="246" height="132" rx="42" fill="#fff" stroke="${CO}" stroke-width="5"/><text x="123" y="35" text-anchor="middle" font-size="24" font-weight="950" fill="${CO}">organism tube</text><rect x="28" y="164" width="64" height="26" rx="8" fill="#EDE8E2" stroke="${CO}" stroke-width="3"/><text x="60" y="184" text-anchor="middle" font-size="18" font-weight="950" fill="${CO}">${st.koh?"KOH":"no KOH"}</text><path d="M96 112 H214" stroke="#9A826E" stroke-width="6"/><text x="157" y="105" text-anchor="middle" font-size="18" font-weight="950" fill="${CO}">gauze</text>${m.live?Array.from({length:7},(_,i)=>`<ellipse cx="${118+(i%4)*24}" cy="${136+Math.floor(i/4)*22}" rx="13" ry="9" fill="${st.organism==="maggot"?"#D7B38C":"#8ACB6A"}" stroke="${CO}" stroke-width="2"/>`).join(""):`<g>${[0,1,2,3,4].map(i=>`<circle cx="${120+i*18}" cy="140" r="9" fill="#CCC4BB" stroke="${CO}" stroke-width="2"/>`).join("")}</g>`}</g><g transform="translate(306 154)"><rect width="302" height="28" rx="14" fill="#fff" stroke="${CO}" stroke-width="4"/><line x1="0" x2="302" y1="14" y2="14" stroke="#BCD7FF" stroke-width="5"/><circle class="resp-drop" cx="${x}" cy="14" r="16" fill="#E9573F" stroke="${CO}" stroke-width="4"/><text x="151" y="-20" text-anchor="middle" font-size="21" font-weight="950" fill="${CO}">capillary tube</text><text x="151" y="62" text-anchor="middle" font-size="20" font-weight="950" fill="${CO}">movement ${m.movement} mm min⁻¹ → towards organisms</text></g><g transform="translate(64 314)"><rect width="552" height="38" rx="18" fill="#fff" stroke="${CO}" stroke-width="3"/><text x="276" y="25" text-anchor="middle" font-size="18" font-weight="950" fill="${CO}">Control: boiled seeds or glass beads of the same volume in the same water bath.</text></g></svg>`; }
function respYeastSvg(st,m){ return `<svg viewBox="0 0 680 390" role="img" aria-label="Yeast and glucose anaerobic respiration tube with oil layer, limewater and carbon dioxide bubbles"><rect width="680" height="390" rx="18" fill="#FFF8EC"/><path d="M0 304 H680 V390 H0Z" fill="#E4CFB0"/><g transform="translate(92 54)"><path d="M34 0 H214 L192 274 H56Z" fill="#F7FBFF" stroke="${CO}" stroke-width="5"/><path d="M60 100 H188 L178 260 H70Z" fill="#F0D391" opacity=".85"/><path d="M58 84 H190" stroke="#BF925D" stroke-width="12" opacity="${st.oxygen==="off"?1:.18}"/><text x="124" y="30" text-anchor="middle" font-size="22" font-weight="950" fill="${CO}">yeast + glucose</text><text x="124" y="79" text-anchor="middle" font-size="19" font-weight="950" fill="${CO}">${st.oxygen==="off"?"oil layer: no O₂":"oxygen present"}</text>${Array.from({length:Math.min(24,Math.round(m.yco2/3))},(_,i)=>`<circle cx="${88+(i*31)%72}" cy="${224-((i*27+st.t*38)%126)}" r="${4+i%4}" fill="#fff" stroke="#4CA9D8" stroke-width="2"/>`).join("")}</g><g transform="translate(382 98)"><rect x="0" y="0" width="184" height="174" rx="26" fill="${m.yco2>22?"#F3E3A2":"#D9F2FF"}" stroke="${CO}" stroke-width="5"/><text x="92" y="34" text-anchor="middle" font-size="24" font-weight="950" fill="${CO}">limewater</text><text x="92" y="86" text-anchor="middle" font-size="28" font-weight="950" fill="${CO}">${m.yco2>22?"milky":"clear"}</text><text x="92" y="132" text-anchor="middle" font-size="20" font-weight="900" fill="${CO}">CO₂ ${m.yco2} min⁻¹</text></g><text x="340" y="346" text-anchor="middle" font-size="21" font-weight="950" fill="${CO}">${st.oxygen==="off"?"Anaerobic: glucose → ethanol + CO₂ + 2 ATP":"With oxygen: yeast uses aerobic respiration more"}</text></svg>`; }
function respCellSvg(st,m){ const anaer=st.oxygen==="off"; return `<svg viewBox="0 0 680 430" role="img" aria-label="Cell respiration pathways showing cytoplasm, mitochondrion, cristae, matrix and ATP yield"><rect width="680" height="430" rx="18" fill="#F7FAFF"/><text x="96" y="42" text-anchor="middle" font-size="24" font-weight="950" fill="${CO}">cytoplasm</text><g transform="translate(36 78)"><rect width="214" height="226" rx="28" fill="#E8F1FF" stroke="${CO}" stroke-width="4"/><text x="107" y="42" text-anchor="middle" font-size="22" font-weight="950" fill="${CO}">glycolysis</text><text x="107" y="90" text-anchor="middle" font-size="20" font-weight="900" fill="${CO}">glucose 6C</text><text x="107" y="132" text-anchor="middle" font-size="24" font-weight="950" fill="#3FA06B">↓</text><text x="107" y="166" text-anchor="middle" font-size="20" font-weight="900" fill="${CO}">2 pyruvate 3C</text><text x="107" y="210" text-anchor="middle" font-size="20" font-weight="950" fill="#D48A00">net 2 ATP</text></g><g transform="translate(324 54)"><path d="M72 10 C174 -18 292 44 284 148 C276 256 148 306 62 246 C-26 184 -18 38 72 10Z" fill="#FFD9B8" stroke="${CO}" stroke-width="5"/><path d="M70 32 C154 8 254 58 250 146 C246 222 144 266 78 222 C12 178 4 56 70 32Z" fill="#FFEFE2" stroke="#B85F4B" stroke-width="4"/><text x="142" y="34" text-anchor="middle" font-size="24" font-weight="950" fill="${CO}">mitochondrion</text>${[0,1,2,3,4].map(i=>`<path d="M64 ${76+i*28} C106 ${48+i*28} 138 ${104+i*28} 184 ${76+i*28} S236 ${104+i*28} 248 ${84+i*28}" fill="none" stroke="#D86C58" stroke-width="9" stroke-linecap="round"/>`).join("")}<text x="142" y="154" text-anchor="middle" font-size="22" font-weight="950" fill="${CO}">matrix</text><text x="142" y="214" text-anchor="middle" font-size="22" font-weight="950" fill="${CO}">cristae</text></g><path d="M252 190 C284 184 294 172 320 160" stroke="${anaer?"#B9A99A":"#3FA06B"}" stroke-width="7" fill="none" marker-end="url(#respArr)"/><defs><marker id="respArr" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="${anaer?"#B9A99A":"#3FA06B"}"/></marker></defs>${anaer?`<g transform="translate(280 318)"><rect width="354" height="62" rx="18" fill="#FFF0EC" stroke="#E9573F" stroke-width="4"/><text x="177" y="25" text-anchor="middle" font-size="21" font-weight="950" fill="${CO}">No oxygen: pyruvate stays in cytoplasm</text><text x="177" y="50" text-anchor="middle" font-size="20" font-weight="950" fill="${CO}">${st.cell==="yeast"?"ethanol + CO₂, 2 ATP":"lactic acid, 2 ATP, oxygen debt"}</text></g>`:`<g transform="translate(286 318)"><rect width="348" height="62" rx="18" fill="#E6F8EC" stroke="#3FA06B" stroke-width="4"/><text x="174" y="25" text-anchor="middle" font-size="21" font-weight="950" fill="${CO}">O₂ final hydrogen acceptor → water</text><text x="174" y="50" text-anchor="middle" font-size="20" font-weight="950" fill="${CO}">about 38 ATP per glucose</text></g>`}<text x="340" y="398" text-anchor="middle" font-size="19" font-weight="950" fill="${CO}">Mitochondrion: outer membrane · cristae · matrix</text></svg>`; }

SIM_CH.enzyme = { title:"Enzyme Rate Detective", mins:15, story:"Use the molecular view and bench to prove how active-site shape controls rate.", missions:[
  { ic:"🔑", name:"Find optimum", tasks:[
    {type:"goal",ic:"🙂",do:"Choose <b>🙂 Salivary amylase</b> and set pH near 7.",look:"Enzyme + pH controls",target:"amylase at pH 6.5–7.5",check:p=>p.kind==="amylase"&&p.pH>=6.5&&p.pH<=7.5,hold:.3,why:"Amylase works best near neutral pH."},
    {type:"goal",ic:"🌡️",do:"Warm to the human optimum: 35–40 °C.",look:"Temperature slider",target:"35–40 °C",check:p=>p.temp>=35&&p.temp<=40&&!p.denatured,meter:p=>({v:p.temp,min:0,max:70,lo:35,hi:40,unit:" °C",label:"Temperature"}),why:"More kinetic energy gives more successful collisions up to the optimum."},
    {type:"read",ic:"⚡",do:"Read the live reaction rate at the optimum.",look:"Rate tile",need:p=>p.optimum,needTxt:"amylase, pH near 7, 35–40 °C.",fields:[["Rate",p=>p.rate,3,"/100"]],why:"This is close to the maximum for these enzyme and substrate amounts."}]},
  { ic:"📈", name:"Saturation", tasks:[
    {type:"goal",ic:"⬡",do:"Raise <b>⬡ Substrate</b> above 85%.",look:"Substrate slider",target:"substrate ≥ 85%",check:p=>p.substrate>=85,meter:p=>({v:p.substrate,min:0,max:100,lo:85,hi:100,unit:"%",label:"Substrate"}),why:"Many active sites are occupied."},
    {type:"pick",ic:"🧱",do:"Why does the curve level off at high substrate?",look:"Graph plateau",need:p=>p.substrate>=85,needTxt:"Substrate above 85%.",opts:["All active sites are occupied, so enzyme concentration is limiting","The substrate has been denatured by heat","The enzyme has become a product","pH is no longer important"],miss:["","Substrate does not denature; proteins do.","Enzymes are reused and are not changed into products.","pH still affects active-site shape."],why:"This flat part is Vmax: adding more substrate cannot make more active sites."},
    {type:"goal",ic:"📈",do:"Tap <b>📈 Save curve</b> at least once.",look:"Graph card",target:"one ghost curve",check:p=>p.ghosts>=1,hold:.2,why:"A ghost curve lets you compare fair-test runs."}]},
  { ic:"🚫", name:"Inhibitors", tasks:[
    {type:"goal",ic:"🚫",do:"Turn on <b>🚫 Competitive</b> inhibitor with high substrate.",look:"Inhibitor buttons",target:"competitive + high substrate",check:p=>p.inhibitor==="comp"&&p.highSub,hold:.3,why:"Substrate and inhibitor compete for the same active site."},
    {type:"goal",ic:"🧲",do:"Now choose <b>🧲 Non-competitive</b> inhibitor.",look:"Inhibitor buttons",target:"non-competitive",check:p=>p.inhibitor==="non",hold:.3,why:"It binds elsewhere and changes the active-site shape."},
    {type:"pick",ic:"🔍",do:"Which inhibitor is NOT overcome by more substrate?",look:"Compare rates",opts:["Non-competitive inhibitor","Competitive inhibitor","The substrate itself","Low temperature"],miss:["","More substrate can outcompete an active-site blocker.","Substrate is the reactant, not an inhibitor.","Low temperature is reversible and not an inhibitor."],why:"Non-competitive inhibition lowers Vmax because fewer enzymes have a working active site."}]},
  { ic:"🔥", name:"Explain", tasks:[
    {type:"goal",ic:"🔥",do:"Heat above 62 °C to denature the enzyme.",look:"Temperature slider",target:"denatured",check:p=>p.denatured,hold:.2,why:"Heat permanently changes the active-site shape, so substrate no longer fits."},
    {type:"fill",ic:"✍️",do:"Complete the exam sentence.",text:"At low temperature enzymes are {inactive|denatured}, but at very high temperature they are {denatured|only slowed}; the active site {changes shape|becomes more complementary}.",why:"Cold is reversible; high heat can permanently denature the protein."},
    {type:"pick",ic:"🧪",do:"Which is a fair test for temperature?",opts:["Change temperature only; keep pH, enzyme and substrate amounts constant","Change temperature and pH together","Use a different enzyme in every tube","Measure some tubes for 1 minute and others for 10 minutes"],miss:["","Then you cannot tell which variable caused the change.","Enzyme type changes the active site and optimum pH.","Time must be the same for a fair rate comparison."],why:"A fair test changes one independent variable and controls the others."},
    {type:"order",ic:"🔢",do:"Put the lock-and-key steps in order.",items:["Substrate collides with the active site","Enzyme–substrate complex forms","Reaction happens and products form","Products leave the active site","Enzyme is reused"],why:"The enzyme is not used up, so it can catalyse another reaction."}]}] };
SIM_CH.photo = { title:"Pondweed Photosynthesis Trial", mins:15, story:"Find the limiting factor and connect the bubble count to chloroplast reactions.", missions:[
  { ic:"💡", name:"Light test", tasks:[
    {type:"goal",ic:"💡",do:"Move the lamp closer than 20 cm.",look:"Lamp-distance slider",target:"distance ≤ 20 cm",check:p=>p.distance<=20,meter:p=>({v:p.distance,min:8,max:80,lo:8,hi:20,unit:" cm",label:"Lamp distance"}),why:"Closer lamp means higher light intensity because intensity follows 1/d²."},
    {type:"read",ic:"🫧",do:"Read the oxygen bubble rate.",look:"O₂ bubbles tile",need:p=>p.closeLamp,needTxt:"Lamp closer than 20 cm.",fields:[["Bubbles per minute",p=>p.bubbles,3,"min⁻¹"]],why:"Oxygen bubbles are evidence that photosynthesis is producing O₂."},
    {type:"pick",ic:"📈",do:"On the rising part of a light graph, what limits the rate?",look:"Rate graph",opts:["Light intensity","Soda lime","Oxygen concentration","The cuticle"],miss:["","Soda lime is for CO₂ absorption in experiments, not this graph.","O₂ is a product here, not the usual limiting factor.","The cuticle reduces water loss; it is not on this graph."],why:"When the graph rises with the x-axis factor, that factor is limiting."}]},
  { ic:"CO₂", name:"Raise plateau", tasks:[
    {type:"goal",ic:"CO₂",do:"Raise <b>CO₂ (NaHCO₃)</b> above 70%.",look:"CO₂ slider",target:"CO₂ ≥ 70%",check:p=>p.co2>=70,meter:p=>({v:p.co2,min:0,max:100,lo:70,hi:100,unit:"%",label:"CO₂"}),why:"More CO₂ raises carbon fixation and can lift the plateau."},
    {type:"goal",ic:"📈",do:"Tap <b>📈 Save curve</b> for a ghost line.",look:"Graph card",target:"one ghost curve",check:p=>p.ghosts>=1,hold:.2,why:"Ghost lines compare plateaus at different CO₂ or temperature."},
    {type:"pick",ic:"🧱",do:"At high light, why does the graph become flat?",look:"Plateau",need:p=>p.intensity>50,needTxt:"Use high light intensity.",opts:["CO₂ or temperature becomes the limiting factor","Light is being reflected by oxygen","The plant has stopped respiring","Water no longer contains hydrogen"],miss:["","Oxygen does not reflect light in this set-up.","Respiration continues all the time.","Water still provides hydrogen; another factor is limiting."],why:"A plateau means increasing light alone no longer increases the rate."}]},
  { ic:"🌈", name:"Pigment colour", tasks:[
    {type:"goal",ic:"🟢",do:"Choose <b>🟢 Green</b> light.",look:"Light colour buttons",target:"green light",check:p=>p.colour==="green",hold:.3,why:"Chlorophyll reflects much green light, so photosynthesis is slow."},
    {type:"pick",ic:"🔴",do:"Which colours are absorbed best by chlorophyll?",look:"Light colour buttons",opts:["Red and blue","Green only","Yellow and green","White only because colours disappear"],miss:["","Leaves look green because much green light is reflected.","Yellow-green is not the main absorption peak.","White contains all colours; red and blue are the useful parts."],why:"The action spectrum is high in red and blue light."},
    {type:"fill",ic:"✍️",do:"Finish the limiting-factor rule.",text:"If the graph is {rising|flat}, the x-axis factor is limiting; if it is {flat|rising}, another factor is limiting.",why:"This is the key graph-reading rule for HKDSE."}]},
  { ic:"🟢", name:"Inside chloroplast", tasks:[
    {type:"goal",ic:"🟢",do:"Switch to <b>🟢 Chloroplast</b> view.",look:"View buttons",target:"chloroplast view",check:p=>p.view==="chloroplast",hold:.2,why:"The zoom shows where the two stages happen."},
    {type:"order",ic:"🔢",do:"Put the photosynthesis stages in order.",items:["Chlorophyll absorbs light on thylakoids","Photolysis splits water and releases oxygen","ATP and NADPH are made","CO₂ combines with RuBP in the stroma","Triose phosphate makes glucose or starch"],why:"Light reactions supply ATP and NADPH for the Calvin cycle."},
    {type:"fill",ic:"✍️",do:"Link the two stages.",look:"Chloroplast view",need:p=>p.view==="chloroplast",needTxt:"Switch to chloroplast view.",text:"The light-dependent reactions make {ATP and NADPH|glucose and RuBP}; the Calvin cycle uses them to reduce {GP|oxygen} to triose phosphate.",why:"ATP and NADPH from thylakoids power sugar formation in the stroma."},
    {type:"pick",ic:"🏙️",do:"Why enrich CO₂ in a Hong Kong greenhouse?",opts:["To raise yield when CO₂ is the limiting factor","To remove oxygen from plants","To make chlorophyll reflect red light","To stop all respiration"],miss:["","Plants still need and produce oxygen in different processes.","Pigment colour does not change that way.","Respiration continues in living cells."],why:"Greenhouse growers add the limiting factor only when it can raise the rate."}]}] };
SIM_CH.resp = { title:"Respiration Evidence Lab", mins:15, story:"Use apparatus and the cell view to compare aerobic and anaerobic respiration.", missions:[
  { ic:"📏", name:"Respirometer", tasks:[
    {type:"goal",ic:"📏",do:"Switch to <b>📏 Respirometer</b> mode.",look:"Mode buttons",target:"respirometer mode",check:p=>p.view==="respiro",hold:.2,why:"This apparatus measures oxygen uptake."},
    {type:"goal",ic:"⚪",do:"Use living organisms with <b>⚪ Soda lime / KOH</b> on.",look:"Respirometer controls",target:"living + KOH",check:p=>p.respirometerReady,hold:.3,why:"Soda lime absorbs CO₂ so volume change shows O₂ uptake."},
    {type:"read",ic:"📏",do:"Read the liquid movement per minute.",look:"Movement tile",need:p=>p.respirometerReady,needTxt:"living organisms and KOH on.",fields:[["Movement",p=>p.movement,.6,"mm min⁻¹"]],why:"The coloured liquid moves towards the organisms as oxygen is used."}]},
  { ic:"⚖️", name:"Control", tasks:[
    {type:"goal",ic:"🥔",do:"Choose <b>🥔 Boiled seeds</b> or <b>⚪ Glass beads</b>.",look:"Respirometer buttons",target:"control tube",check:p=>p.control,hold:.3,why:"A control has the same volume but no active respiration."},
    {type:"pick",ic:"⚪",do:"Why is soda lime / KOH used?",look:"Respirometer set-up",opts:["It absorbs CO₂ so gas-volume fall is due to O₂ uptake","It makes seeds germinate faster","It supplies glucose to maggots","It colours oxygen red"],miss:["","Germination depends on living seed activity, not KOH.","No glucose is supplied by KOH.","The red drop is coloured liquid, not oxygen."],why:"CO₂ is removed, so oxygen uptake pulls the liquid along the capillary."},
    {type:"fill",ic:"✍️",do:"Complete the control sentence.",look:"Control set-up",need:p=>p.control,needTxt:"Choose boiled seeds or glass beads.",text:"The control tube contains {boiled seeds or glass beads|extra KOH only} of the same {volume|colour}, so any movement due to organisms can be compared fairly.",why:"Keep volume and temperature the same; only living respiration should differ."}]},
  { ic:"🍞", name:"Fermentation", tasks:[
    {type:"goal",ic:"🍞",do:"Switch to <b>🍞 Yeast tube</b>, <b>🍞 Yeast</b> and <b>O₂ Off</b>.",look:"Mode, oxygen and cell-type controls",target:"anaerobic yeast",check:p=>p.yeastReady,hold:.3,why:"Oil excludes oxygen, so yeast ferments glucose."},
    {type:"read",ic:"CO₂",do:"Read the yeast CO₂ bubble rate.",look:"Yeast tube",need:p=>p.yeastReady,needTxt:"yeast tube with O₂ off.",fields:[["CO₂ bubbles",p=>p.yco2,4,"min⁻¹"]],why:"Yeast anaerobic respiration makes ethanol and carbon dioxide."},
    {type:"pick",ic:"🍞",do:"What product makes bread dough rise?",look:"Yeast tube bubbles",opts:["Carbon dioxide","Lactic acid","Oxygen","Soda lime"],miss:["","Lactic acid is the muscle anaerobic product.","Oxygen is absent in anaerobic fermentation.","Soda lime absorbs CO₂; it is not made by yeast."],why:"CO₂ bubbles expand the dough."}]},
  { ic:"🧬", name:"Cell pathway", tasks:[
    {type:"goal",ic:"🧬",do:"Switch to <b>🧬 Cell view</b> with <b>O₂ On</b>.",look:"Mode and oxygen buttons",target:"aerobic cell",check:p=>p.view==="cell"&&p.oxygen==="on",hold:.3,why:"Oxygen lets pyruvate enter mitochondria."},
    {type:"order",ic:"🔢",do:"Put aerobic respiration stages in order.",items:["Glycolysis in cytoplasm","Pyruvate enters mitochondrion","Krebs cycle in matrix releases CO₂","Hydrogen passes along carriers on cristae","Oxygen accepts hydrogen to form water"],why:"Cytoplasm first, then matrix, then inner membrane cristae."},
    {type:"pick",ic:"🏃",do:"What explains oxygen debt after hard exercise?",opts:["Extra O₂ is needed to break down lactic acid after anaerobic respiration","Extra O₂ is stored in soda lime","Yeast in muscles makes ethanol","Glycolysis stops forever"],miss:["","Soda lime is lab apparatus, not in muscles.","Human muscle forms lactic acid, not ethanol.","Glycolysis can continue if NAD is regenerated."],why:"Anaerobic muscle respiration makes lactic acid; later oxygen helps remove it."},
    {type:"fill",ic:"✍️",do:"Compare ATP yield.",text:"Aerobic respiration gives about {38|2} ATP per glucose; anaerobic respiration gives {2|38} ATP.",why:"HKDSE level uses about 38 ATP for aerobic respiration and 2 for anaerobic."}]}] };
